package review.dual;
import review.mysql.*;
import review.mobile.*;
import ai_study_planner.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
class DualLedgerH2Tests {
 static final String PASSWORD="synthetic-dual-only-password";
 java.sql.Connection bootstrap;String id,url;ConfigurableApplicationContext ctx;DualLedgerRuntime.Fixture f;DualLedgerRuntime.Wire wire;DualLedgerRuntime.Gate gate;DualLedgerScenario s;JdbcTemplate jdbc;
 @BeforeEach void open()throws Exception{
  assertThrows(ClassNotFoundException.class,()->Class.forName("com.mysql.cj.jdbc.Driver"));id=UUID.randomUUID().toString();url="jdbc:h2:mem:dual_"+id+";MODE=MySQL;DB_CLOSE_DELAY=-1";bootstrap=DualLedgerProfile.offlineH2(url,id);
  var p=DualLedgerServer.offlineProperties(id,new BCryptPasswordEncoder(12).encode(PASSWORD));p.put("spring.datasource.url",url);ctx=DualLedgerServer.context(p,false);jdbc=ctx.getBean(JdbcTemplate.class);try(var c=jdbc.getDataSource().getConnection()){assertEquals("H2 JDBC Driver",c.getMetaData().getDriverName());assertEquals(url.split(";")[0],c.getMetaData().getURL());}
  assertInstanceOf(org.springframework.mock.web.MockServletContext.class,((org.springframework.web.context.WebApplicationContext)ctx).getServletContext());f=DualLedgerRuntime.seed(ctx);wire=DualLedgerRuntime.install(ctx);gate=ctx.getBean(DualLedgerRuntime.Gate.class);gate.open(f);s=new DualLedgerScenario(ctx,id,f,wire,gate);
 }
 @AfterEach void close()throws Exception{if(bootstrap!=null)bootstrap.close();if(ctx!=null){ctx.close();try(var c=java.sql.DriverManager.getConnection(url,"sa","");var st=c.createStatement()){st.execute("SHUTDOWN");}catch(Exception e){throw new AssertionError(e);}}}
 @Test void bothLedgersFullScenarioAndProtectedFinal()throws Exception{var result=s.run(PASSWORD);assertEquals(true,result.get("goalBAndFinalPreserved"));assertEquals(0,result.get("realAiCalls"));assertEquals("H2_MEMORY",result.get("dataBackend"));assertEquals(2,result.get("studyLedgerRows"));assertEquals(5,result.get("aiLedgerRows"));assertEquals(false,result.get("processRestartVerified"));assertEquals(3,wire.counts().get("DAILY_COACHING"));assertEquals(2,wire.counts().get("STUDY_SUMMARY"));}
 @Test void jpaAndReviewDdlCommitInOneTransaction(){var tx=new org.springframework.transaction.support.TransactionTemplate(ctx.getBean(org.springframework.transaction.PlatformTransactionManager.class));tx.execute(st->{String k=DualLedgerScenario.key();jdbc.update("INSERT INTO study_log_requests(user_id,operation,request_key,goal_id,request_hash,request_state,created_at) VALUES(1,'STUDY_LOG_SAVE',?,? ,?,'PROCESSING',CURRENT_TIMESTAMP)",k,f.goalA(),"a".repeat(64));var log=new StudyLog();log.setUserId(1L);log.setSubjectId(f.subjectA());log.setStudyDate(f.day().minusDays(1));log.setStudyMinutes(40);var saved=ctx.getBean(StudyLogRepository.class).saveAndFlush(log);jdbc.update("UPDATE study_log_requests SET request_state='COMPLETED',log_id=?,response_json='{}' WHERE request_key=?",saved.getLogId(),k);return null;});assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM study_log_requests",Integer.class));}
 @Test void authCsrfAndUnsupportedWritesCannotReachWire()throws Exception{
  assertEquals(401,s.mvc.perform(get("/goals")).andReturn().getResponse().getStatus());s.login(PASSWORD);assertEquals(403,s.mvc.perform(post("/study-logs").session(s.session)).andReturn().getResponse().getStatus());for(String path:List.of("/study-question","/study-reschedule-save","/gpt-weekly-coaching"))assertEquals(403,s.write(path,f.goalA(),DualLedgerScenario.key(),Map.of()).getResponse().getStatus());assertEquals(403,s.read("/llm-coaching",f.goalA(),Map.of()).getResponse().getStatus());assertEquals(0,wire.counts().get("DAILY_COACHING"));assertEquals(0,wire.counts().get("STUDY_SUMMARY"));
 }
 @Test void readsDoNotWriteAndMockMarkerIsNotH2Claim()throws Exception{s.login(PASSWORD);var before=DualLedgerRuntime.snapshot(jdbc,DualLedgerProfile.TABLES);for(String path:List.of("/goals","/subjects","/study-logs","/analysis-summary","/ai-generation-policy","/study-log-idempotency"))assertEquals(200,s.read(path,f.goalA(),Map.of()).getResponse().getStatus(),path);var policy=DualLedgerScenario.tree(s.read("/ai-generation-policy",f.goalA(),Map.of()));assertEquals(DualLedgerRuntime.MARKER,policy.path("testMode").asText());assertEquals(DualLedgerProfile.MODE,policy.path("storageMode").asText());assertEquals(before,DualLedgerRuntime.snapshot(jdbc,DualLedgerProfile.TABLES));}
 @Test void wrongRunGoalAndModelCannotGenerate()throws Exception{s.login(PASSWORD);assertEquals(403,s.write("/llm-coaching",f.goalB(),DualLedgerScenario.key(),DualLedgerScenario.aiBody()).getResponse().getStatus());assertEquals(403,s.mvc.perform(post("/llm-coaching").session(s.session).header("X-CSRF-TOKEN",s.token).header("X-Integration-Run",UUID.randomUUID()).header("Idempotency-Key",DualLedgerScenario.key()).param("goalId",""+f.goalA()).contentType("application/json").content("{}")).andReturn().getResponse().getStatus());assertEquals(400,s.write("/llm-coaching",f.goalA(),DualLedgerScenario.key(),Map.of("confirmPaidCall",true,"expectedModel","wrong")).getResponse().getStatus());assertEquals(0,wire.counts().get("DAILY_COACHING"));}
 @Test void recoveryModeAllowsOnlyGetsAndLeavesWholeDbUnchanged()throws Exception{var recovery=new DualLedgerRuntime.Gate(ctx,id,true);recovery.open(f);var flow=new DualLedgerScenario(ctx,id,f,wire,recovery);flow.login(PASSWORD);var before=DualLedgerRuntime.snapshot(jdbc,DualLedgerProfile.TABLES);assertEquals(403,flow.write("/study-logs",f.goalA(),DualLedgerScenario.key(),flow.log()).getResponse().getStatus());assertEquals(200,flow.read("/study-logs",f.goalA(),Map.of()).getResponse().getStatus());assertEquals(before,DualLedgerRuntime.snapshot(jdbc,DualLedgerProfile.TABLES));}
 @Test void quiesceBlocksNewRequests()throws Exception{s.login(PASSWORD);gate.quiesce(200);assertEquals(503,s.read("/goals",f.goalA(),Map.of()).getResponse().getStatus());}
 @Test void scenarioFailureRecordsFirstLogAndPreservesBaseline(@org.junit.jupiter.api.io.TempDir java.nio.file.Path directory)throws Exception{var checkedTables=new ArrayList<>(DualLedgerProfile.TABLES);checkedTables.remove("integration_requests");var baseline=DualLedgerRuntime.snapshot(jdbc,checkedTables);var controller=ctx.getBean(StudyLogController.class);var original=org.springframework.test.util.ReflectionTestUtils.getField(controller,"idempotency");var broken=org.mockito.Mockito.mock(StudyLogIdempotencyService.class);org.mockito.Mockito.when(broken.requireKey()).thenReturn(true);org.mockito.Mockito.when(broken.save(org.mockito.ArgumentMatchers.anyLong(),org.mockito.ArgumentMatchers.any(),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.any())).thenThrow(new StudyLogIdempotencyFailure(503,"IDEMPOTENCY_STORAGE_UNAVAILABLE","synthetic masked failure"));s.diagnostics.journal(directory);try{org.springframework.test.util.ReflectionTestUtils.setField(controller,"idempotency",broken);var failure=assertThrows(DualLedgerDiagnostics.Failure.class,()->s.run(PASSWORD));var proof=s.diagnostics.failure(failure);assertEquals("FIRST_LOG",proof.get("scenarioStep"));assertEquals(503,proof.get("actualHttpStatus"));assertEquals(baseline,DualLedgerRuntime.snapshot(jdbc,checkedTables));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM integration_requests",Integer.class));assertEquals(0,wire.counts().get("DAILY_COACHING"));}finally{org.springframework.test.util.ReflectionTestUtils.setField(controller,"idempotency",original);}}
 @Test void sameKeyInDifferentLedgersDoesNotCollide()throws Exception{s.login(PASSWORD);String k=DualLedgerScenario.key();assertEquals(200,s.write("/study-logs",f.goalA(),k,s.log()).getResponse().getStatus());assertEquals(200,s.write("/llm-coaching",f.goalA(),k,DualLedgerScenario.aiBody()).getResponse().getStatus());assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM study_log_requests",Integer.class));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM ai_generation_requests",Integer.class));assertEquals(2,jdbc.queryForObject("SELECT COUNT(*) FROM integration_requests",Integer.class));}
}
